<?php

declare(strict_types=1);

/*
 * docs:lint (sidebar) — fails when a docs page has no entry in the docs site
 * sidebar, so it builds and has a URL but nothing links to it.
 *
 * A page is listed when the sidebar names its slug (`slug: '...'`) or when it
 * sits under an autogenerated directory (`autogenerate: { directory: '...' }`).
 * An `index` page's slug is its directory. The home page (the root index) is
 * not a sidebar entry and is skipped.
 *
 * Usage:
 *   php bin/docs-sidebar-lint.php [--config=<astro.config.mjs>] [--pages=<docs dir>]
 *
 * Both options exist for the check's own tests; the defaults are the real site.
 *
 * Exits 1 on any unlisted page, a missing config, a config with no sidebar
 * entries, or a docs directory with no pages.
 */

$repositoryRoot = dirname(__DIR__);
$options = getopt('', ['config:', 'pages:']);
$configFile = is_string($options['config'] ?? null) ? $options['config'] : $repositoryRoot . '/docs/astro.config.mjs';
$pagesRoot = rtrim(
    is_string($options['pages'] ?? null) ? $options['pages'] : $repositoryRoot . '/packages/docs-markdown/docs',
    '/',
);

if (!is_file($configFile)) {
    fwrite(STDERR, "docs:lint sidebar config not found at $configFile.\n");
    exit(1);
}

$config = (string) file_get_contents($configFile);
preg_match_all('/\bslug:\s*([\'"])(.*?)\1/', $config, $slugMatches);
preg_match_all('/\bautogenerate:\s*\{\s*directory:\s*([\'"])(.*?)\1/', $config, $directoryMatches);
$slugs = array_map(static fn (string $slug): string => trim($slug, '/'), $slugMatches[2]);
$directories = array_map(static fn (string $directory): string => trim($directory, '/'), $directoryMatches[2]);

if ($slugs === [] && $directories === []) {
    fwrite(STDERR, "docs:lint found no sidebar entries in $configFile. Refusing to pass an empty sidebar.\n");
    exit(1);
}

$pages = [];

if (is_dir($pagesRoot)) {
    $iterator = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($pagesRoot, FilesystemIterator::SKIP_DOTS),
    );

    foreach ($iterator as $file) {
        if ($file instanceof SplFileInfo && in_array($file->getExtension(), ['md', 'mdx'], true)) {
            $pages[] = substr($file->getPathname(), strlen($pagesRoot) + 1);
        }
    }
}

if ($pages === []) {
    fwrite(STDERR, "docs:lint found no docs pages under $pagesRoot. Refusing to pass an empty scan.\n");
    exit(1);
}

sort($pages);
$unlisted = [];

foreach ($pages as $page) {
    $slug = (string) preg_replace('/\.mdx?$/', '', $page);
    $slug = $slug === 'index' ? '' : (string) preg_replace('#/index$#', '', $slug);

    if ($slug === '' || in_array($slug, $slugs, true)) {
        continue;
    }

    foreach ($directories as $directory) {
        if (str_starts_with($slug . '/', $directory . '/')) {
            continue 2;
        }
    }

    $unlisted[] = $page;
}

if ($unlisted !== []) {
    foreach ($unlisted as $page) {
        fwrite(STDERR, "$page has no sidebar entry\n");
    }

    fwrite(STDERR, sprintf(
        "\ndocs:lint failed: %d docs page(s) have no sidebar entry. Add each one to the sidebar in %s.\n",
        count($unlisted),
        str_replace($repositoryRoot . '/', '', $configFile),
    ));
    exit(1);
}

echo sprintf("docs:lint passed: %d docs pages, every docs page has a sidebar entry.\n", count($pages));
